// CSD_RATIONALE_BEGIN
// SMILES isocyanate CSD — attempt 41: expand guidance diversity, extend penalization window.
//
// Diagnosis of attempt 40 failure (7% accuracy):
//   The primary regression vs. attempt 9 (20%) was caused by narrowing guidance
//   from 10 cross-class examples (aromatic + aliphatic + cyclic + heteroaromatic)
//   to 6 non-aromatic examples. The model's output distribution collapsed to
//   ~7 unique molecules. Aromatic guidance is essential for structural diversity.
//   The maxSpanLength=20 cap was a secondary negative (forces premature closure,
//   reducing structural complexity and novelty).
//
// Root cause of attempt 9 plateau at 20%:
//   With 10 guidance templates, the model samples ~20 distinct structures.
//   To reach 36 unique molecules per 100 runs, we need more templates and a
//   broader distribution over chemical space.
//
// Strategy: Build from attempt 9 (best known) with two targeted changes:
//
//   1. GUIDANCE EXPANSION to 25 diverse examples spanning:
//      - Bicyclic aliphatics (decalin-2-yl, tetrahydronaphthyl, indanyl)
//      - Substituted phenyls (4-methoxy, 4-chloro, 3-methyl, 3-fluoro)
//      - Heteroaromatics (2-pyridyl, 3-thienyl, 3-furyl)
//      - Heteroaliphatic rings (morpholinyl, THF-2-yl, tetrahydrothiopyranyl)
//      - Functional group-bearing aliphatics (difluoroethyl, ester, sulfonyl)
//      - Long/branched aliphatics (hexyl, neopentyl, 3-pentyl)
//      - Benzylic variants (4-fluorobenzyl, 4-pyridylmethyl)
//      - Alpha-substituted benzylic (1-phenylethan-1-yl)
//      Hypothesis: 25 diverse templates → model distributes probability mass
//      over ≥36 distinct structures per 100 runs.
//
//   2. EXTENDED PENALIZATION WINDOW: penalize ["C","CC","O"] for first 10
//      tokens (vs. 6 in attempt 9) to push more aggressively away from
//      common scaffolds (ethyl, propyl, simple phenyl isocyanates).
//
//   3. REMOVE maxSpanLength=20 cap (was added in attempt 40, hurt accuracy).
//      The hasNCO==0 check for O=C=N format already provides a "keep extending"
//      diversity mechanism without needing an artificial cap.
//
// Preserved unchanged from attempt 9 (proven):
//   - SafePenalizedConstrainedStep early phase (scaffold diversity)
//   - SafeTemperatureConstrainedStep T=1.6 mid phase
//   - GroupBoostedConstrainedStep late phase (≥22 tokens)
//   - hasNCO check (O=C=N format never fires → always extends → more variety)
//   - CloseSpanWithinBudget fallback for budget exhaustion
//   - minSpanLength=5
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   OpenConstrainedSpan: sets currentConstrainedOut := [], and parser.IsValidPrefix([])
//     holds by method precondition. ✓
//
//   Branch "IsComplete && |span|>=5 && hasNCO>0" — CloseConstrainedSpan:
//     sets insideConstrainedOut := false, making the implication vacuously true;
//     currentConstrainedOut := []. ✓
//
//   Branch "IsComplete && |span|>=5 && hasNCO==0" — SafeTemperatureConstrainedStep:
//     hard-masks to parser-valid tokens plus EOS. If EOS: break (no append).
//     Otherwise AppendConstrainedToken preserves IsValidPrefix by its postcondition. ✓
//
//   Else branch (SafePenalizedConstrainedStep / SafeTemperatureConstrainedStep /
//   GroupBoostedConstrainedStep): all three helpers hard-mask to parser-valid tokens
//   plus EOS. AppendConstrainedToken preserves IsValidPrefix. Inner EOS-close path
//   is gated on IsCompletePrefix, then CloseConstrainedSpan clears the span. ✓
//
//   CloseSpanWithinBudget postcondition: insideOut ==> IsValidPrefix(currentOut). ✓
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
//   OpenConstrainedSpan: appends "<<" (+1 to |generated|), steps+1. Preserved. ✓
//
//   Complete+length>=5+close (CloseConstrainedSpan): appends ">>" (+1), steps+1.
//     Loop guard ensures steps < maxSteps. Preserved. ✓
//
//   Complete+length>=5+extend: steps+1; AppendConstrainedToken adds ≤1 token to
//     |generated|; EOS adds 0. Preserved. ✓
//
//   Else-branch: steps+1; AppendConstrainedToken adds ≤1 token to |generated|.
//     Inner EOS-close adds steps+1 and ">>" (+1 to |generated|), both guarded by
//     steps < maxSteps. Total ≤ steps+2, |generated| ≤ |generatedPrefix|+steps+2.
//     At entry to inner close, steps already incremented and steps < maxSteps
//     checked, so max total within budget. Preserved. ✓
//
//   CloseSpanWithinBudget with closeBudget=maxSteps-steps:
//     |cg| <= |generated|+closeBudget <= |generatedPrefix|+maxSteps; steps:=maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;

helpers.AppendTaskGuidance(lm, "Generate exactly one novel SMILES for an isocyanate (R-N=C=O). Output ONLY the SMILES string with no explanation. Choose diverse and unusual R groups from many structural classes. Examples of varied isocyanate structures (generate something DIFFERENT from these): O=C=NC1CC2CCCCC2C1 O=C=NC1CCc2ccccc21 O=C=NC1Cc2ccccc2C1 O=C=NC(C)c1ccccc1 O=C=Nc1ccc(OC)cc1 O=C=Nc1ccc(Cl)cc1 O=C=Nc1cc(C)ccc1 O=C=Nc1cccc(F)c1 O=C=Nc1ccccn1 O=C=Nc1ccsc1 O=C=Nc1ccoc1 O=C=NCC(C)(C)C O=C=NCCC(C)C O=C=NCCCCCC O=C=NCC(F)F O=C=NCCCC(=O)OC O=C=NCS(=O)(=O)C O=C=NC1COCCN1 O=C=NC1CCOC1 O=C=NC1CCSCC1 O=C=NCCN(C)C O=C=NCc1ccncc1 O=C=NCc1ccc(F)cc1 O=C=NC(C)(C)CC O=C=NC(CC)CCC");

if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

var minSpanLength: nat := 5;
var tokenCount: nat := 0;
var commonTokens: seq<Token> := ["C", "CC", "O"];

while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength {
    var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
    var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
    if hasNCO > 0 {
      // Explicit N=C=O format confirmed — close the span
      if steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      } else {
        break;
      }
    } else {
      // O=C=N format (hasNCO==0) — keep extending for structural diversity
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.6, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        tokenCount := tokenCount + 1;
      }
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := eosToken;

    if tokenCount < 10 {
      // Early phase: penalize common scaffold tokens for diversity (extended to 10 tokens)
      next := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, commonTokens, 4.0, eosToken
      );
    } else if tokenCount < 22 {
      // Mid phase: high temperature for structural variety
      next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.6, eosToken
      );
    } else {
      // Late phase: group-boosted to leverage caller vocabulary hints
      next := helpers.GroupBoostedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
      );
    }

    steps := steps + 1;
    if next == eosToken {
      // EOS received: close if span is complete, long enough, and valid isocyanate
      if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength && steps < maxSteps {
        var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
        var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
        if hasNCO > 0 {
          var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        }
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
      tokenCount := tokenCount + 1;
    }
  }
}

// Fallback: use remaining budget to close any open span
if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

